export const PARENT_ORACLE_SHA='916ec07a3606d0b5412d8721a3fa1eef977410d1411e10d69b10d54dbcae8b23';
export const PARENT_CONTRACT=[{"owner":"sichos-271-position-0","section":271,"position":0,"source_index":1,"fields":{"he":"אמר: הלא החנוני דרכו להקיף בהקפה, שיתנו לו לאחר זמן, ומדוע לא יאמר האדם איזה קפיטליך תהלים או ללמד או לעשות שאר מצוות, ויהיה מנח ומוכן אצלו לעת הצרך?! כי יהיה זמן שיצטרך לזה, שיגבה שכרו ופעלתו. לא יהא שנותן החנוני (נ\"א ומדוע לא יהא כהחנוני שנותן) סחורה בהקפה וכו'?!","he_nikud":"אָמַר: הֲלֹא הַחֶנְוָנִי דַּרְכּוֹ לְהַקִּיף בְּהַקָּפָה, שֶׁיִּתְּנוּ לוֹ לְאַחַר זְמַן, וּמַדּוּעַ לֹא יֹאמַר הָאָדָם אֵיזֶה קַפִּיטְלִיךְ תְּהִלִּים אוֹ לִלְמֹד אוֹ לַעֲשׂוֹת שְׁאָר מִצְווֹת, וְיִהְיֶה מֻנָּח וּמוּכָן אֶצְלוֹ לְעֵת הַצֹּרֶךְ?! כִּי יִהְיֶה זְמַן שֶׁיִּצְטָרֵךְ לָזֶה, שֶׁיִּגְבֶּה שְׂכָרוֹ וּפְעֻלָּתוֹ. לֹא יְהֵא שֶׁנּוֹתֵן הַחֶנְוָנִי (נ\"א וּמַדּוּעַ לֹא יְהֵא כְּהַחֶנְוָנִי שֶׁנּוֹתֵן) סְחוֹרָה בְּהַקָּפָה וְכוּ'?!","en":"He said: “Is it not the shopkeeper’s practice to extend credit, so that he will be paid later? And why should a person not recite some chapters of Psalms, or study, or perform other commandments, so that this will be laid aside and ready for him for a time of need?! For a time will come when he will need this, when he will collect his reward and his recompense. Should it not be that the shopkeeper gives (another version: And why should one not be like the shopkeeper who gives) merchandise on credit, and so forth?!”"},"history":{"earlier_supplied_English":"The Rebbe said, “A storekeeper will sell to you on credit, to be paid at a later date. “Why not do the same with spiritual goods? Do a few good deeds, or say a few Psalms or words of Torah, so that they can be put aside and ready when you need them. You will then be able to call on this merit and like the storekeeper who sells on credit.”","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-271-original.json","original_owner_pointer":"/segments/0"},"required_qualifications":[{"id":"author271-origin-notice-sichos-271-position-0","owner":"sichos-271-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."},{"id":"sichos-271-position-0-ending-reading","owner":"sichos-271-position-0","placement":"after-owning-paragraph","role":"current-reader-limitation","text":"The supplied Hebrew’s main reading at the final question does not explicitly say “like the shopkeeper.” The English renders that wording literally; the parenthetical alternative explicitly includes the comparison. The words “merchandise on credit, and so forth” form the shared ending of both readings."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-271-position-0","englishUTF8SHA256":"ee67021d0524ff9dea18421207104c9d13de88624fb149a471e7c77961cce50c"}},{"owner":"sichos-271-position-1","section":271,"position":1,"source_index":2,"fields":{"he":"(ולא שמעתי שיחה זו בעצמי מפיו הקדוש רק מפי אחר. וכפי הנראה שהיה בזה שיחה נאה ולא זכיתי לשמעה).","he_nikud":"(וְלֹא שָׁמַעְתִּי שִׂיחָה זוֹ בְּעַצְמִי מִפִּיו הַקָּדוֹשׁ רַק מִפִּי אַחֵר. וּכְפִי הַנִּרְאֶה שֶׁהָיָה בָּזֶה שִׂיחָה נָאָה וְלֹא זָכִיתִי לְשָׁמְעָהּ).","en":"(And I did not hear this discourse myself from his holy mouth, but only from another person. And it appears that there was a fine discourse about this, and I did not merit to hear it.)"},"history":{"earlier_supplied_English":"I did not hear this discussion from the Rebbe himself, but from one of my colleagues. It appears that many more beautiful thoughts were expressed at that time, but this is all I was worthy of recording.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-271-original.json","original_owner_pointer":"/segments/1"},"required_qualifications":[{"id":"author271-origin-notice-sichos-271-position-1","owner":"sichos-271-position-1","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-271-position-1","englishUTF8SHA256":"3768b6ac1f1aaaba2ff8926e7fff706cbe5d16227135c74288077912be703a74"}},{"owner":"sichos-272-position-0","section":272,"position":0,"source_index":1,"fields":{"he":"איש אחד מהקלי עולם, נכנס אצלו בעיר אחת והתפאר לפניו על אשר הוא מלמד בלשונות הגויים, כי היה עתה בבתי ערכאות שלהם ולא ידעו הסופרים שלהם תבה אחת לקרותה היטב והוא פרשה להם. והיה לזה האיש הנ\"ל גדלות גדול מאד על שהוא מלמד כל כך בלשונותיהם.","he_nikud":"אִישׁ אֶחָד מֵהַקַּלֵּי עוֹלָם, נִכְנַס אֶצְלוֹ בְּעִיר אַחַת וְהִתְפָּאֵר לְפָנָיו עַל אֲשֶׁר הוּא מְלֻמָּד בִּלְשׁוֹנוֹת הַגּוֹיִים, כִּי הָיָה עַתָּה בְּבָתֵּי עַרְכָּאוֹת שֶׁלָּהֶם וְלֹא יָדְעוּ הַסּוֹפְרִים שֶׁלָּהֶם תֵּבָה אַחַת לִקְרוֹתָהּ הֵיטֵב וְהוּא פֵּרְשָׁהּ לָהֶם. וְהָיָה לְזֶה הָאִישׁ הַנַּ\"ל גַּדְלוּת גָּדוֹל מְאֹד עַל שֶׁהוּא מְלֻמָּד כָּל כָּךְ בִּלְשׁוֹנוֹתֵיהֶם.","en":"A frivolous man came to the Rebbe in a certain city and boasted before him that he was learned in the languages of the nations, for he had just been in their courts, and their scribes did not know how to read one word properly, and he explained it to them. And this man had very great conceit because he was so learned in their languages."},"history":{"earlier_supplied_English":"An irreligious man came to the Rebbe in a certain city and boasted that he was an expert in languages. He had recently been in a government office and was able to interpret a word that even their scribes did not know. He was very conceited because of this knowledge.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-272-original.json","original_owner_pointer":"/segments/0"},"required_qualifications":[{"id":"author271-origin-notice-sichos-272-position-0","owner":"sichos-272-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."},{"id":"author271-272-0-classification","text":"קלי עולם is rendered “frivolous” here. The Hebrew does not explicitly classify the man as irreligious.","owner":"sichos-272-position-0","placement":"after-owning-paragraph","role":"current-reader-limitation"}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-272-position-0","englishUTF8SHA256":"287449c5ff14b438cfc07a4ded1b7eed609668699f9fdf543490f761cef60e34"}},{"owner":"sichos-272-position-1","section":272,"position":1,"source_index":2,"fields":{"he":"ואחר כך יצא האיש הנ\"ל והיה רבנו ז\"ל מתלוצץ ממנו על שיש לו גדלות כל כך משטותים כאלה.","he_nikud":"וְאַחַר כָּךְ יָצָא הָאִישׁ הַנַּ\"ל וְהָיָה רַבֵּנוּ ז\"ל מִתְלוֹצֵץ מִמֶּנּוּ עַל שֶׁיֵּשׁ לוֹ גַּדְלוּת כָּל כָּךְ מִשְּׁטוּתִים כָּאֵלֶּה.","en":"And afterward the man left, and the Rebbe, of blessed memory, ridiculed him for having so much conceit because of such foolish things."},"history":{"earlier_supplied_English":"When the man left, the Rebbe ridiculed him for such foolish conceit.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-272-original.json","original_owner_pointer":"/segments/1"},"required_qualifications":[{"id":"author271-origin-notice-sichos-272-position-1","owner":"sichos-272-position-1","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-272-position-1","englishUTF8SHA256":"46cf70755e816c34bee7040f559bb4d6fa0d09522138d47809a92dd77e03c796"}},{"owner":"sichos-272-position-2","section":272,"position":2,"source_index":3,"fields":{"he":"וישב שם איש אחד מאנשיו שהיה למדן מפלג וירא ה'. וענה ואמר לרבנו ז\"ל: \"אפשר טוב יותר מה שיש לו גדלות מדברי שטות ממי שיש לו גדלות ח\"ו מדברי תורה?\"","he_nikud":"וְיָשַׁב שָׁם אִישׁ אֶחָד מֵאֲנָשָׁיו שֶׁהָיָה לַמְדָן מֻפְלָג וִירֵא ה'. וְעָנָה וְאָמַר לְרַבֵּנוּ ז\"ל: \"אֶפְשָׁר טוֹב יוֹתֵר מַה שֶּׁיֵּשׁ לוֹ גַּדְלוּת מִדִּבְרֵי שְׁטוּת מִמִּי שֶׁיֵּשׁ לוֹ גַּדְלוּת ח\"ו מִדִּבְרֵי תּוֹרָה?\"","en":"And one of the Rebbe’s disciples, an extraordinary, God-fearing scholar, was sitting there. And he answered and said to the Rebbe, of blessed memory, “Maybe it is better to be conceited because of something foolish than to be conceited, Heaven forbid, because of one’s knowledge of Torah?”"},"history":{"earlier_supplied_English":"One of the Rebbe’s disciples, an extraordinary, God-fearing scholar, was sitting there. He said to the Rebbe, “Maybe it is better to be conceited because of something foolish than to be conceited, Heaven forbid, because of one’s knowledge of Torah.”","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-272-original.json","original_owner_pointer":"/segments/2"},"required_qualifications":[{"id":"author271-origin-notice-sichos-272-position-2","owner":"sichos-272-position-2","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-272-position-2","englishUTF8SHA256":"b682e93f77d2dfbe3140d8a8937f7f95df7e1c1925befa925a51d380994fbf4f"}},{"owner":"sichos-272-position-3","section":272,"position":3,"source_index":4,"fields":{"he":"ושתק רבנו ז\"ל איזה שעה קלה.","he_nikud":"וְשָׁתַק רַבֵּנוּ ז\"ל אֵיזֶה שָׁעָה קַלָּה.","en":"And the Rebbe, of blessed memory, was silent for a brief moment."},"history":{"earlier_supplied_English":"The Rebbe was silent for a moment.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-272-original.json","original_owner_pointer":"/segments/3"},"required_qualifications":[{"id":"author271-origin-notice-sichos-272-position-3","owner":"sichos-272-position-3","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-272-position-3","englishUTF8SHA256":"794d4171b8e3abdf6f968d248e8c8cad73573fd05743172659c8305113d44875"}},{"owner":"sichos-272-position-4","section":272,"position":4,"source_index":5,"fields":{"he":"ואחר כך ענה ואמר: אדרבא נהפך הוא! וכמו שאמרו רבותינו ז\"ל (ברכות סא:): לענין ר' עקיבא שנתפס בתפיסה שאמר לו פפוס: אשריך רבי עקיבא שנתפסת על דברי תורה, ואוי לו לפפוס שנתפס על דברים בטלים.","he_nikud":"וְאַחַר כָּךְ עָנָה וְאָמַר: אַדְּרַבָּא נַהֲפֹךְ הוּא! וּכְמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ ז\"ל (בְּרָכוֹת סא:): לְעִנְיַן ר' עֲקִיבָא שֶׁנִּתְפַּס בִּתְפִיסָה שֶׁאָמַר לוֹ פַּפּוּס: אַשְׁרֶיךָ רַבִּי עֲקִיבָא שֶׁנִּתְפַּסְתָּ עַל דִּבְרֵי תּוֹרָה, וְאוֹי לוֹ לְפַפּוּס שֶׁנִּתְפַּס עַל דְּבָרִים בְּטֵלִים.","en":"And afterward he answered and said: “On the contrary, the opposite is true!” And as our Sages, of blessed memory, said (Berachos 61b), concerning Rabbi Akiva, who was imprisoned: Papus said to him, “Happy are you, Rabbi Akiva, for you were imprisoned for the sake of the Torah, and woe to Papus, who was imprisoned for idle matters.”"},"history":{"earlier_supplied_English":"Then he said, “No. The opposite is true. The Talmud tells us that when Rabbi Akiva was in prison, Papus said to him, 'Happy are you, Rabbi Akiva, for you were imprisoned for the sake of the Torah. Woe is to Papus, for I was imprisoned for mere foolishness’” ( Berakhot 61b) .","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-272-original.json","original_owner_pointer":"/segments/4"},"required_qualifications":[{"id":"author271-origin-notice-sichos-272-position-4","owner":"sichos-272-position-4","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-272-position-4","englishUTF8SHA256":"21b00b1ebdba09b0496461c5fc03786914e0328c8d6a76bd377eced618baa63b"}},{"owner":"sichos-272-position-5","section":272,"position":5,"source_index":6,"fields":{"he":"כי ענש הגדלות הוא תפיסה. (וכמו שמבאר בהתורה \"חותם בתוך חותם\" סימן כב לקוטי מוהר\"ן חלק ראשון ועין בלקוטי תנינא סימן ס\"ג בהתורה המתחלת כשיש מלחמות וכו', כי שם מובא מענין התפיסה של רבי עקיבא עין שם).","he_nikud":"כִּי עֹנֶשׁ הַגַּדְלוּת הוּא תְּפִיסָה. (וּכְמוֹ שֶׁמְּבֹאָר בְּהַתּוֹרָה \"חוֹתָם בְּתוֹךְ חוֹתָם\" סִימָן כב לִקּוּטֵי מוֹהֲרָ\"ן חֵלֶק רִאשׁוֹן וְעַיֵּן בְּלִקּוּטֵי תִּנְיָנָא סִימָן ס\"ג בְּהַתּוֹרָה הַמַּתְחֶלֶת כְּשֶׁיֵּשׁ מִלְחָמוֹת וְכוּ', כִּי שָׁם מוּבָא מֵעִנְיַן הַתְּפִיסָה שֶׁל רַבִּי עֲקִיבָא עַיֵּן שָׁם).","en":"For the punishment for conceit is imprisonment. (And as is explained in the teaching “A Seal within a Seal,” section 22 of Likutay Moharan, Part One; and see Likutay Tinyana, section 63, in the teaching beginning “When there are wars,” etc., for the matter of Rabbi Akiva’s imprisonment is brought there; see there.)"},"history":{"earlier_supplied_English":"It is brought in Likutey Moharan (I, 22:12) that the punishment for conceit is imprisonment (see also Likutey Moharan II, 63) . Also discussed is the imprisonment of Rabbi Akiva.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-272-original.json","original_owner_pointer":"/segments/5"},"required_qualifications":[{"id":"author271-origin-notice-sichos-272-position-5","owner":"sichos-272-position-5","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-272-position-5","englishUTF8SHA256":"4467656776ea4cff04bfc319ac39828af71a2c9b073646c2f971701abe3c6741"}},{"owner":"sichos-272-position-6","section":272,"position":6,"source_index":7,"fields":{"he":"נמצא, שהגדלות שענשו תפיסה, כשהוא על דברי תורה, טוב יותר מהגדלות על דברים בטלים.","he_nikud":"נִמְצָא, שֶׁהַגַּדְלוּת שֶׁעָנְשׁוֹ תְּפִיסָה, כְּשֶׁהוּא עַל דִּבְרֵי תּוֹרָה, טוֹב יוֹתֵר מֵהַגַּדְלוּת עַל דְּבָרִים בְּטֵלִים.","en":"Thus, conceit whose punishment is imprisonment, when it concerns matters of Torah, is better than conceit concerning idle matters."},"history":{"earlier_supplied_English":"It is better to be imprisoned for the conceit of Torah than to be conceited because of foolishness.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-272-original.json","original_owner_pointer":"/segments/6"},"required_qualifications":[{"id":"author271-origin-notice-sichos-272-position-6","owner":"sichos-272-position-6","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-272-position-6","englishUTF8SHA256":"b45d20087e87b2955f8ef38691b4aefbddfdc6ac6e8058aa6c556823bf38abd7"}},{"owner":"sichos-273-position-0","section":273,"position":0,"source_index":1,"fields":{"he":"אמר: טוב להאדם להרגיל את עצמו שיוכל להחיות את עצמו עם איזה נגון.","he_nikud":"אָמַר: טוֹב לְהָאָדָם לְהַרְגִּיל אֶת עַצְמוֹ שֶׁיּוּכַל לְהַחֲיוֹת אֶת עַצְמוֹ עִם אֵיזֶה נִגּוּן.","en":"The Rebbe said: It is good to accustom yourself so that you can enliven yourself with a melody."},"history":{"earlier_supplied_English":"The Rebbe said, “It is good to make a habit of inspiring yourself with a melody.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-273-original.json","original_owner_pointer":"/segments/0"},"required_qualifications":[{"id":"author271-origin-notice-sichos-273-position-0","owner":"sichos-273-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."},{"id":"author271-273-0-delimiter","text":"The colon introduces the Rebbe’s reported words. The earlier English leaves its quotation open across this paragraph boundary; no missing Hebrew prose is implied.","owner":"sichos-273-position-0","placement":"after-owning-paragraph","role":"current-reader-limitation"}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-273-position-0","englishUTF8SHA256":"5357264552e8eecb93a3ea9c9adf5c5b0a6c01583b5e8917a8ecf1a2acc9a919"}},{"owner":"sichos-273-position-1","section":273,"position":1,"source_index":2,"fields":{"he":"כי נגון הוא דבר גדול וגבוה מאד מאד, ויש לו כח גדול לעורר ולהמשיך את לב האדם להשם יתברך.","he_nikud":"כִּי נִגּוּן הוּא דָּבָר גָּדוֹל וְגָבוֹהַּ מְאֹד מְאֹד, וְיֵשׁ לוֹ כֹּחַ גָּדוֹל לְעוֹרֵר וּלְהַמְשִׁיךְ אֶת לֵב הָאָדָם לְהַשֵּׁם יִתְבָּרַךְ.","en":"For melody is a great and very, very lofty thing, and it has great power to arouse a person’s heart and draw it toward God, blessed be He."},"history":{"earlier_supplied_English":"“Song is a great elevated concept. It can arouse your heart and draw it toward God.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-273-original.json","original_owner_pointer":"/segments/1"},"required_qualifications":[{"id":"author271-origin-notice-sichos-273-position-1","owner":"sichos-273-position-1","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-273-position-1","englishUTF8SHA256":"bdbad97d2507ed72a0c33b2fa17068a0c96435a0253a617096c9f7c82284b112"}},{"owner":"sichos-273-position-2","section":273,"position":2,"source_index":3,"fields":{"he":"ואפלו מי שאינו יכול לנגן, אף על פי כן בביתו ובינו לבין עצמו יוכל להחיות את עצמו באיזה נגון כפי שיוכל לזמר אותו, כי מעלת הנגון אין לשער.","he_nikud":"וַאֲפִלּוּ מִי שֶׁאֵינוֹ יָכוֹל לְנַגֵּן, אַף עַל פִּי כֵן בְּבֵיתוֹ וּבֵינוֹ לְבֵין עַצְמוֹ יוּכַל לְהַחֲיוֹת אֶת עַצְמוֹ בְּאֵיזֶה נִגּוּן כְּפִי שֶׁיּוּכַל לְזַמֵּר אוֹתוֹ, כִּי מַעֲלַת הַנִּגּוּן אֵין לְשַׁעֵר.","en":"And even if you cannot sing, nevertheless, at home and in private you can enliven yourself with a melody as well as you are able to sing it, for the loftiness of melody is beyond all measure."},"history":{"earlier_supplied_English":"“Even if you cannot sing well, you can still inspire yourself with a melody sung to the best of your ability while alone or at home. The loftiness of melody is beyond all measure.”","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-273-original.json","original_owner_pointer":"/segments/2"},"required_qualifications":[{"id":"author271-origin-notice-sichos-273-position-2","owner":"sichos-273-position-2","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."},{"id":"author271-273-2-melody-action","text":"Here “sing” renders לנגן in light of לזמר in the same sentence. In other contexts the melody term can refer to playing music; no single technical sense is imposed on every occurrence.","owner":"sichos-273-position-2","placement":"after-owning-paragraph","role":"current-reader-limitation"}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-273-position-2","englishUTF8SHA256":"2a6a124e71002e8cbaf0da6b8b6445c1c65203a89a138eecdcd6b75030876759"}},{"owner":"sichos-273-position-3","section":273,"position":3,"source_index":4,"fields":{"he":"וכבר מבאר בדברי רבנו ז\"ל, כמה תורות גבוהות מענין נגון.","he_nikud":"וּכְבָר מְבֹאָר בְּדִבְרֵי רַבֵּנוּ ז\"ל, כַּמָּה תּוֹרוֹת גְּבוֹהוֹת מֵעִנְיַן נִגּוּן.","en":"And several lofty teachings concerning melody have already been explained in the words of the Rebbe, of blessed memory."},"history":{"earlier_supplied_English":"The Rebbe’s works contain towering lessons speaking of song. 361 Likutey Moharan I, 3, 8:9, 38:4, 42, 49:7, 282; ibid., II, 8:1, 31, 92.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-273-original.json","original_owner_pointer":"/segments/3"},"required_qualifications":[{"id":"author271-origin-notice-sichos-273-position-3","owner":"sichos-273-position-3","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-273-position-3","englishUTF8SHA256":"fcb2af4d6b0ee7a1207ce7783336277f34afafee4bf2ae7b9f86a3d797be1251"}},{"owner":"sichos-273-position-4","section":273,"position":4,"source_index":5,"fields":{"he":"ועין בסוף המעשה של השבעה בעטלירס שם מרמז קצת מעלת הנגון. כי מבאר שם שעקר רפואת הבת מלכה שנפלה חלשות הוא על ידי נגון, הינו על ידי עשרה מיני נגינה כמו שמבאר שם עין שם. והבן מאד עד היכן הדברים מגיעים:","he_nikud":"וְעַיֵּן בְּסוֹף הַמַּעֲשֶׂה שֶׁל הַשִּׁבְעָה בֶּעטְלֶירְס שָׁם מְרֻמָּז קְצָת מַעֲלַת הַנִּגּוּן. כִּי מְבֹאָר שָׁם שֶׁעִקַּר רְפוּאַת הַבַּת מַלְכָּה שֶׁנָּפְלָה חַלָּשׁוּת הוּא עַל יְדֵי נִגּוּן, הַיְנוּ עַל יְדֵי עֲשָׂרָה מִינֵי נְגִינָה כְּמוֹ שֶׁמְּבֹאָר שָׁם עַיֵּן שָׁם. וְהָבֵן מְאֹד עַד הֵיכָן הַדְּבָרִים מַגִּיעִים:","en":"And see the end of the story of the Seven Beggars, where something of the loftiness of melody is hinted at. For it is explained there that the main cure of the princess who fell into a faint is through melody, namely through the ten types of melody, as is explained there; see there. And understand very well how far these matters reach:"},"history":{"earlier_supplied_English":"The tale of “The Seven Beggars” ( Rabbi Nachman's Stories #13; see “ His Wisdom ” #149-151) also alludes to the importance of melody. The unconscious princess is cured mainly through melody, through the ten categories of song. Understand the implications of this.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-273-original.json","original_owner_pointer":"/segments/4"},"required_qualifications":[{"id":"author271-origin-notice-sichos-273-position-4","owner":"sichos-273-position-4","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."},{"id":"author271-273-4-faintness","text":"שנפלה חלשות describes falling into faintness or weakness. “Fell into a faint” does not specify a clinical state of unconsciousness.","owner":"sichos-273-position-4","placement":"after-owning-paragraph","role":"current-reader-limitation"}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-273-position-4","englishUTF8SHA256":"2997b0147808feda6112f4574e5c4c48ac48e1e83848129b066ebb48cf2e5a44"}},{"owner":"sichos-273-position-5","section":273,"position":5,"source_index":6,"fields":{"he":"כי גם הנשמה הקדושה של כל אחד מישראל היא נקראת בת מלך כידוע והיא מנחת במקום שמנחת אצל כל אחד ואחד, עיפה ויגעה וחלושה בעוונותיה שהם העשרה מיני חצים, שזרק וירה בה המלך שתפסה כמו שמבאר שם. וצריכין צדיק בעל כח גדול שיוכל לכנס לתוך כל המקומות שנפלה לשם ולהוציא ממנה כל העשרה מיני חצים, ולידע כל העשרה מיני דפיקין כדי שידע איך צריכין לרפואתה. ולנגן כל העשרה מיני נגינה, כי עקר רפואתה על ידי נגון ושמחה.","he_nikud":"כִּי גַּם הַנְּשָׁמָה הַקְּדוֹשָׁה שֶׁל כָּל אֶחָד מִיִּשְׂרָאֵל הִיא נִקְרֵאת בַּת מֶלֶךְ כַּיָּדוּעַ וְהִיא מֻנַּחַת בְּמָקוֹם שֶׁמֻּנַּחַת אֵצֶל כָּל אֶחָד וְאֶחָד, עֲיֵפָה וִיגֵעָה וַחֲלוּשָׁה בַּעֲווֹנוֹתֶיהָ שֶׁהֵם הָעֲשָׂרָה מִינֵי חִצִּים, שֶׁזָּרַק וְיָרָה בָּהּ הַמֶּלֶךְ שֶׁתְּפָסָהּ כְּמוֹ שֶׁמְּבֹאָר שָׁם. וּצְרִיכִין צַדִּיק בַּעַל כֹּחַ גָּדוֹל שֶׁיּוּכַל לִכְנֹס לְתוֹךְ כָּל הַמְּקוֹמוֹת שֶׁנָּפְלָה לְשָׁם וּלְהוֹצִיא מִמֶּנָּה כָּל הָעֲשָׂרָה מִינֵי חִצִּים, וְלֵידַע כָּל הָעֲשָׂרָה מִינֵי דְּפִיקִין כְּדֵי שֶׁיֵּדַע אֵיךְ צְרִיכִין לִרְפוּאָתָהּ. וּלְנַגֵּן כָּל הָעֲשָׂרָה מִינֵי נְגִינָה, כִּי עִקַּר רְפוּאָתָהּ עַל יְדֵי נִגּוּן וְשִׂמְחָה.","en":"For also the holy soul of every Jew is called a princess—a king’s daughter—as is known, and she lies where she lies within each and every person, weary, exhausted and weakened by her sins, which are the ten types of arrows that the king who captured her hurled and shot into her, as is explained there. And a tzaddik of great power is needed, who can enter all the places where she has fallen and remove all ten types of arrows from her, and know all ten types of pulse beat in order to know how she needs to be healed. And he must play all ten types of melody, for her main cure is through melody and joy."},"history":{"earlier_supplied_English":"The divine soul in every Jew is a princess – a king’s daughter. She is weary and faint because of her sins. She is held captive by an evil king and is shot with ten poisonous arrows. Only a great tzaddik has the power to enter every place where the soul has fallen and remove all ten arrows from her. In order to heal her, he must be able to discern all ten types of pulse beat. He must know all ten categories of song, for her main cure is through melody and joy (see Likutey Moharan II, 92; “ His Wisdom ” #129) .","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-273-original.json","original_owner_pointer":"/segments/5"},"required_qualifications":[{"id":"author271-origin-notice-sichos-273-position-5","owner":"sichos-273-position-5","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."},{"id":"author271-273-5-resumed-need","text":"“He must play” continues the preceding statement that a tzaddik of great power is needed. The Hebrew describes playing the ten kinds of melody, not merely knowing them; it does not identify a particular tzaddik.","owner":"sichos-273-position-5","placement":"after-owning-paragraph","role":"current-reader-limitation"}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-273-position-5","englishUTF8SHA256":"20eeadcf8173436261b856c6eaf6c1984ee8c3fde833912c328208ca955db8da"}},{"owner":"sichos-273-position-6","section":273,"position":6,"source_index":7,"fields":{"he":"והבן שם עוד דברים מתוך דבר. והעקר להוציא משם עצות טובות לשוב להשם יתברך באמת כי 'לא המדרש הוא העקר אלא המעשה' (אבות א).","he_nikud":"וְהָבֵן שָׁם עוֹד דְּבָרִים מִתּוֹךְ דָּבָר. וְהָעִקָּר לְהוֹצִיא מִשָּׁם עֵצוֹת טוֹבוֹת לָשׁוּב לְהַשֵּׁם יִתְבָּרַךְ בֶּאֱמֶת כִּי 'לֹא הַמִּדְרָשׁ הוּא הָעִקָּר אֶלָּא הַמַּעֲשֶׂה' (אָבוֹת א).","en":"And understand further matters there, one thing from another. And the main thing is to derive good counsels from there to return to God, blessed be He, in truth, for “Study is not the main thing, but action” (Avos 1)."},"history":{"earlier_supplied_English":"Taking this as a clue, you can understand more of the story. Use it as a means of returning to God in truth. For, “Study is not the main thing, but action” ( Avot 1:17) .","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-273-original.json","original_owner_pointer":"/segments/6"},"required_qualifications":[{"id":"author271-origin-notice-sichos-273-position-6","owner":"sichos-273-position-6","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-273-position-6","englishUTF8SHA256":"a50eb85951214e051d7fcf1438ac3c4f9a1f01977e5234c349add3f0c17b2a37"}},{"owner":"sichos-274-position-0","section":274,"position":0,"source_index":1,"fields":{"he":"טוב מאד להאדם שיהיה לו חדר מיחד לו לבדו לעסק שם בעבודת ה' בתורה ותפלה. ובפרט התבודדות ושיחה בינו לבין קונו, שלזה צריכין בודאי חדר מיחד.","he_nikud":"טוֹב מְאֹד לְהָאָדָם שֶׁיִּהְיֶה לוֹ חֶדֶר מְיֻחָד לוֹ לְבַדּוֹ לַעֲסֹק שָׁם בַּעֲבוֹדַת ה' בְּתוֹרָה וּתְפִלָּה. וּבִפְרָט הִתְבּוֹדְדוּת וְשִׂיחָה בֵּינוֹ לְבֵין קוֹנוֹ, שֶׁלָּזֶה צְרִיכִין בְּוַדַּאי חֶדֶר מְיֻחָד.","en":"It is very good to have a special room for yourself alone, to engage there in the service of God through Torah study and prayer. And especially for secluded meditation and conversation between yourself and your Maker, you certainly need a special room for this."},"history":{"earlier_supplied_English":"It is very good to have a special room set aside for Torah study and prayer. Such a room is especially beneficial for hitbodedut – secluded meditation and conversation with God (see “ His Wisdom ” #248; Yemey Moharnat #82) .","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-274-original.json","original_owner_pointer":"/segments/0"},"required_qualifications":[{"id":"author271-origin-notice-sichos-274-position-0","owner":"sichos-274-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-274-position-0","englishUTF8SHA256":"c85fda3c617b311ec6b641910fc07647e10438e088d941ad3ad4107d6dc54cc8"}},{"owner":"sichos-275-position-0","section":275,"position":0,"source_index":1,"fields":{"he":"ואמר רבנו ז\"ל: שאפלו הישיבה בעצמה, שיושבין בחדר מיחד לבדו, גם זה טוב מאד.","he_nikud":"וְאָמַר רַבֵּנוּ ז\"ל: שֶׁאֲפִלּוּ הַיְשִׁיבָה בְּעַצְמָהּ, שֶׁיּוֹשְׁבִין בְּחֶדֶר מְיֻחָד לְבַדּוֹ, גַּם זֶה טוֹב מְאֹד.","en":"And the Rebbe, of blessed memory, said that even the sitting itself—sitting alone in a special room—is also very good."},"history":{"earlier_supplied_English":"The Rebbe said that it is very good just to sit in such a special room.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-275-original.json","original_owner_pointer":"/segments/0"},"required_qualifications":[{"id":"author271-origin-notice-sichos-275-position-0","owner":"sichos-275-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-275-position-0","englishUTF8SHA256":"ba7bfb2ad71823628eb7dd943c6ca4443ce6b91bf033f8a2a378a3279b57299a"}},{"owner":"sichos-275-position-1","section":275,"position":1,"source_index":2,"fields":{"he":"ואף על פי כן, אפלו אם אין זוכין שיהיה לו חדר מיחד, אף על פי כן יכולין להתבודד ולדבר בינו לבין קונו.","he_nikud":"וְאַף עַל פִּי כֵן, אֲפִלּוּ אִם אֵין זוֹכִין שֶׁיִּהְיֶה לוֹ חֶדֶר מְיֻחָד, אַף עַל פִּי כֵן יְכוֹלִין לְהִתְבּוֹדֵד וּלְדַבֵּר בֵּינוֹ לְבֵין קוֹנוֹ.","en":"And nevertheless, even if you do not merit to have a special room, nevertheless you can seclude yourself and converse with your Maker."},"history":{"earlier_supplied_English":"Even if you do not have a special room, you can still seclude yourself and converse with God.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-275-original.json","original_owner_pointer":"/segments/1"},"required_qualifications":[{"id":"author271-origin-notice-sichos-275-position-1","owner":"sichos-275-position-1","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-275-position-1","englishUTF8SHA256":"a11271673a8cedb5a1a2469f9822867ecbcff6e86a8d4973042ffe4785465018"}},{"owner":"sichos-275-position-2","section":275,"position":2,"source_index":3,"fields":{"he":"ואמר רבנו ז\"ל: שתחת הטלית הוא גם כן חדר מיחד. כי כשמשלשלין הטלית על עיניו, יכולין לדבר בינו לבין קונו מה שרוצין.","he_nikud":"וְאָמַר רַבֵּנוּ ז\"ל: שֶׁתַּחַת הַטַּלִּית הוּא גַּם כֵּן חֶדֶר מְיֻחָד. כִּי כְּשֶׁמְּשַׁלְשְׁלִין הַטַּלִּית עַל עֵינָיו, יְכוֹלִין לְדַבֵּר בֵּינוֹ לְבֵין קוֹנוֹ מַה שֶּׁרוֹצִין.","en":"And the Rebbe, of blessed memory, said that beneath the tallis is also a special room. For when you drape the tallis over your eyes, you can converse between yourself and your Maker about whatever you wish."},"history":{"earlier_supplied_English":"The Rebbe also said that you can create your own special room under your talit . Just drape your talit over your eyes and converse with God as you desire.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-275-original.json","original_owner_pointer":"/segments/2"},"required_qualifications":[{"id":"author271-origin-notice-sichos-275-position-2","owner":"sichos-275-position-2","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-275-position-2","englishUTF8SHA256":"fab15eac6207ae8fe434d2ae3fb9beeef03f5a8ba5a8f373dd99e5f938ee8e53"}},{"owner":"sichos-275-position-3","section":275,"position":3,"source_index":4,"fields":{"he":"גם יכולין להתבודד ולפרש שיחתו כששוכב על מטתו ומכסה עצמו בהסדין (כמבאר במקום אחר) שכך נהג דוד המלך ע\"ה. שזהו בחינת (תהלים ו): \"אשחה בכל לילה מטתי\" וכו'.","he_nikud":"גַּם יְכוֹלִין לְהִתְבּוֹדֵד וּלְפָרֵשׁ שִׂיחָתוֹ כְּשֶׁשּׁוֹכֵב עַל מִטָּתוֹ וּמְכַסֶּה עַצְמוֹ בְּהַסָּדִין (כַּמְבֹאָר בְּמָקוֹם אַחֵר) שֶׁכָּךְ נָהַג דָּוִד הַמֶּלֶךְ ע\"ה. שֶׁזֶּהוּ בְּחִינַת (תְּהִלִּים ו): \"אַשְׂחֶה בְכָל לַיְלָה מִטָּתִי\" וְכוּ'.","en":"You can also seclude yourself and pour out your conversation when lying on your bed and covering yourself with the sheet (as is explained elsewhere), for this was the practice of King David, peace be upon him. This is the aspect of (Psalms 6): “I make my bed swim every night,” etc."},"history":{"earlier_supplied_English":"You can also seclude yourself with God in bed under the covers (see “ His Wisdom ” #68) . This was the custom of King David, as it is written, “I converse every night on my bed” (Psalms 6:7) .","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-275-original.json","original_owner_pointer":"/segments/3"},"required_qualifications":[{"id":"author271-origin-notice-sichos-275-position-3","owner":"sichos-275-position-3","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."},{"id":"author271-275-3-verse-wording","text":"The verb אַשְׂחֶה uses swimming or flooding imagery, not speaking. The Hebrew cites Psalms chapter 6 and refers to another discussion without numbering it.","owner":"sichos-275-position-3","placement":"after-owning-paragraph","role":"current-reader-limitation"}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-275-position-3","englishUTF8SHA256":"12466c9572d1097e77fb9ef5f31ae514c821dd104bae332b009470253df78dfd"}},{"owner":"sichos-275-position-4","section":275,"position":4,"source_index":5,"fields":{"he":"גם יכולין לישב על הספר ויסברו אחרים שהוא לומד, והוא יכול אז לדבר בינו לבין קונו.","he_nikud":"גַּם יְכוֹלִין לְיַשֵּׁב עַל הַסֵּפֶר וְיִסְבְּרוּ אֲחֵרִים שֶׁהוּא לוֹמֵד, וְהוּא יָכוֹל אָז לְדַבֵּר בֵּינוֹ לְבֵין קוֹנוֹ.","en":"You can also sit before a book, and others will suppose that you are studying, and you can then converse between yourself and your Maker."},"history":{"earlier_supplied_English":"You can also converse with God while sitting before an open book. Let others think that you are merely studying.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-275-original.json","original_owner_pointer":"/segments/4"},"required_qualifications":[{"id":"author271-origin-notice-sichos-275-position-4","owner":"sichos-275-position-4","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."},{"id":"author271-275-4-pointed-anomaly","text":"“Sit” follows לישב in the unpointed text and the context of sitting before a book. The supplied vocalized version reads לְיַשֵּׁב, an anomalous form in this sentence. Both Hebrew versions are reproduced unchanged; the intended vocalization is not established by choosing this English reading.","owner":"sichos-275-position-4","placement":"after-owning-paragraph","role":"current-reader-limitation"}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-275-position-4","englishUTF8SHA256":"5d0cc01a6cf7c70453fa7cce432eb9b0415897163b3acdb27058cde10ee6d9e1"}},{"owner":"sichos-275-position-5","section":275,"position":5,"source_index":6,"fields":{"he":"ועוד יש לזה כמה תחבולות למי שחפץ באמת לנהג הנהגה זו של התבודדות העולה על הכל, שהוא יסוד שרש הקדשה והטהרה והתשובה וכו' (כמבאר כבר כמה פעמים).","he_nikud":"וְעוֹד יֵשׁ לָזֶה כַּמָּה תַּחְבּוּלוֹת לְמִי שֶׁחָפֵץ בֶּאֱמֶת לִנְהֹג הַנְהָגָה זוֹ שֶׁל הִתְבּוֹדְדוּת הָעוֹלָה עַל הַכֹּל, שֶׁהוּא יְסוֹד שֹׁרֶשׁ הַקְּדֻשָּׁה וְהַטָּהֳרָה וְהַתְּשׁוּבָה וְכוּ' (כַּמְבֹאָר כְּבָר כַּמָּה פְּעָמִים).","en":"And there are several further methods for this for anyone who truly desires to follow this practice of secluded meditation, which surpasses everything and is the foundation and root of holiness, purity and repentance, etc. (as has already been explained several times)."},"history":{"earlier_supplied_English":"There are many other ways to accomplish this if you truly want to meditate and express your thoughts to God. Above all else, hitbodedut is the root and foundation of holiness and repentance. We have discussed this many times.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-275-original.json","original_owner_pointer":"/segments/5"},"required_qualifications":[{"id":"author271-origin-notice-sichos-275-position-5","owner":"sichos-275-position-5","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-275-position-5","englishUTF8SHA256":"5407b23fb8fbad3db6335ead9302745aab9043ae8985dc2af23d74c69286aca7"}},{"owner":"sichos-275-position-6","section":275,"position":6,"source_index":7,"fields":{"he":"אבל טוב יותר להשתדל שיהיה לו חדר מיחד.","he_nikud":"אֲבָל טוֹב יוֹתֵר לְהִשְׁתַּדֵּל שֶׁיִּהְיֶה לוֹ חֶדֶר מְיֻחָד.","en":"But it is better to try to have a special room."},"history":{"earlier_supplied_English":"It is best to try and have a secluded room.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-275-original.json","original_owner_pointer":"/segments/6"},"required_qualifications":[{"id":"author271-origin-notice-sichos-275-position-6","owner":"sichos-275-position-6","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-275-position-6","englishUTF8SHA256":"4d55807638913d193f2be69944afa1e2be2118cf8ce2e5f4794c79a4682904ea"}},{"owner":"sichos-276-position-0","section":276,"position":0,"source_index":1,"fields":{"he":"ספרו לי, שפעם אחד היה מדבר עם אנשיו. והיה מוכיח ומיסר אותם הרבה בדברים על שעדין אינם עובדים השם יתברך כרצונו, כדרכו הטוב תמיד לדבר רק מזה.","he_nikud":"סִפְּרוּ לִי, שֶׁפַּעַם אֶחָד הָיָה מְדַבֵּר עִם אֲנָשָׁיו. וְהָיָה מוֹכִיחַ וּמְיַסֵּר אוֹתָם הַרְבֵּה בִּדְבָרִים עַל שֶׁעֲדַיִן אֵינָם עוֹבְדִים הַשֵּׁם יִתְבָּרַךְ כִּרְצוֹנוֹ, כְּדַרְכּוֹ הַטּוֹב תָּמִיד לְדַבֵּר רַק מִזֶּה.","en":"They told me that once the Rebbe was speaking with his followers. And he was greatly reproving and chastening them with words because they were still not serving God, blessed be He, according to his will, as was always his good way, to speak only of this."},"history":{"earlier_supplied_English":"The Rebbe was once lecturing his followers, reprimanding them for not serving God as truly befits Him. This was the Rebbe’s constant theme.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-276-original.json","original_owner_pointer":"/segments/0"},"required_qualifications":[{"id":"author271-origin-notice-sichos-276-position-0","owner":"sichos-276-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."},{"id":"author271-276-0-will-referent","text":"כרצונו says “according to his will” without explicitly naming the referent. The English retains this wording rather than deciding between God’s will and the Rebbe’s.","owner":"sichos-276-position-0","placement":"after-owning-paragraph","role":"current-reader-limitation"}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-276-position-0","englishUTF8SHA256":"ec45ffac7227924c9fa712bbc34c1489ab6a22c8f71418e657f388e7bce1b89f"}},{"owner":"sichos-276-position-1","section":276,"position":1,"source_index":2,"fields":{"he":"אחר כך, אחר שהוכיח אותם הרבה, אחר כך נתרצה להם קצת. והתחיל לקרבם ולדבר עמהם רכות. ואמר: \"מה אני רוצה מהם, הלא אף על פי כן הם אנשים כשרים\".","he_nikud":"אַחַר כָּךְ, אַחַר שֶׁהוֹכִיחַ אוֹתָם הַרְבֵּה, אַחַר כָּךְ נִתְרַצָּה לָהֶם קְצָת. וְהִתְחִיל לְקָרְבָם וּלְדַבֵּר עִמָּהֶם רַכּוֹת. וְאָמַר: \"מָה אֲנִי רוֹצֶה מֵהֶם, הֲלֹא אַף עַל פִּי כֵן הֵם אֲנָשִׁים כְּשֵׁרִים\".","en":"Afterward, after he had admonished them greatly, afterward he became somewhat reconciled with them. And he began to draw them close and speak gently with them. And he said, “What do I want from them? After all, nevertheless they are upright people.”"},"history":{"earlier_supplied_English":"After admonishing them, the Rebbe began to make up with his followers. He drew them close and spoke very gently. He said, “What do I want from them? They are still religious people, are they not?”","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-276-original.json","original_owner_pointer":"/segments/1"},"required_qualifications":[{"id":"author271-origin-notice-sichos-276-position-1","owner":"sichos-276-position-1","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-276-position-1","englishUTF8SHA256":"4c2486a1ff5b7e4192619a0be1acc8230680266473bfdae3c9180fb868fe0217"}},{"owner":"sichos-276-position-2","section":276,"position":2,"source_index":3,"fields":{"he":"והתחיל לדבר על לבם וכו'.","he_nikud":"וְהִתְחִיל לְדַבֵּר עַל לִבָּם וְכוּ'.","en":"And the Rebbe began speaking to their hearts, etc."},"history":{"earlier_supplied_English":"The Rebbe then began speaking to their hearts.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-276-original.json","original_owner_pointer":"/segments/2"},"required_qualifications":[{"id":"author271-origin-notice-sichos-276-position-2","owner":"sichos-276-position-2","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-276-position-2","englishUTF8SHA256":"2149593ad9b91074c1b06552a178610bd85da15357d6bfa3756538a3402d7261"}},{"owner":"sichos-276-position-3","section":276,"position":3,"source_index":4,"fields":{"he":"אחר כך ענה ואמר: \"בודאי אתם אנשים כשרים, אך אלו השם יתברך קטן כמו אנכי בודאי היה די מאד העבודה שלכם, אבל באמת השם יתברך גדול מאד מאד, על כן בודאי צריכין לחזק בכל פעם ברצון חזק לעבדו כראוי לעבד אותו יתברך אשר לגדלתו אין חקר\".","he_nikud":"אַחַר כָּךְ עָנָה וְאָמַר: \"בְּוַדַּאי אַתֶּם אֲנָשִׁים כְּשֵׁרִים, אַךְ אִלּוּ הַשֵּׁם יִתְבָּרַךְ קָטָן כְּמוֹ אָנֹכִי בְּוַדַּאי הָיָה דַּי מְאֹד הָעֲבוֹדָה שֶׁלָּכֶם, אֲבָל בֶּאֱמֶת הַשֵּׁם יִתְבָּרַךְ גָּדוֹל מְאֹד מְאֹד, עַל כֵּן בְּוַדַּאי צְרִיכִין לְחַזֵּק בְּכָל פַּעַם בְּרָצוֹן חָזָק לְעָבְדוֹ כָּרָאוּי לַעֲבֹד אוֹתוֹ יִתְבָּרַךְ אֲשֶׁר לִגְדֻלָּתוֹ אֵין חֵקֶר\".","en":"Afterward he answered and said, “You are certainly good people, but if God, blessed be He, were small like me, your service would certainly be quite sufficient. But in truth God, blessed be He, is very, very great; therefore you must certainly strengthen yourself each time with a strong desire to serve Him as it befits serving Him, blessed be He, whose greatness cannot be fathomed.”"},"history":{"earlier_supplied_English":"He said, “You are certainly good people. If God were small like me, your devotion would certainly be sufficient. But God is very, very great! You must gird yourself with a strong desire to serve God properly, for you are serving One 'Whose greatness cannot be fathomed’ (Psalms 145:3) .”","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-276-original.json","original_owner_pointer":"/segments/3"},"required_qualifications":[{"id":"author271-origin-notice-sichos-276-position-3","owner":"sichos-276-position-3","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-276-position-3","englishUTF8SHA256":"cbdc2019a7671ab2dd286b915bc9b82948b57975ff37078f58acae97b4737029"}},{"owner":"sichos-276-position-4","section":276,"position":4,"source_index":5,"fields":{"he":"והרים אז את עצמו והגביה ידיו למעלה, ואמר: \"אבל השם יתברך גדול כל כך וכו'\" כנ\"ל, ונשא ידיו למעלה בתנועה נפלאה לרמז על הפלגת גדלתו יתברך.","he_nikud":"וְהֵרִים אָז אֶת עַצְמוֹ וְהִגְבִּיהַּ יָדָיו לְמַעְלָה, וְאָמַר: \"אֲבָל הַשֵּׁם יִתְבָּרַךְ גָּדוֹל כָּל כָּךְ וְכוּ'\" כַּנַּ\"ל, וְנָשָׂא יָדָיו לְמַעְלָה בִּתְנוּעָה נִפְלָאָה לְרַמֵּז עַל הַפְלָגַת גְּדֻלָּתוֹ יִתְבָּרַךְ.","en":"And the Rebbe then raised himself and lifted his hands upward, and said, “But God, blessed be He, is so great, etc.,” as mentioned above, and he lifted his hands upward with a wondrous movement to hint at the exceptional immensity of His greatness, blessed be He."},"history":{"earlier_supplied_English":"The Rebbe then raised himself and lifted his hands over his head. He repeated the words, “But God is so great ….” Then he then lifted his hands, using them to express God’s greatness.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-276-original.json","original_owner_pointer":"/segments/4"},"required_qualifications":[{"id":"author271-origin-notice-sichos-276-position-4","owner":"sichos-276-position-4","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-276-position-4","englishUTF8SHA256":"3477594e94fe9e53e638caf4ce3a9e1cd81ce824aaaa49a56f707e88982dcb31"}},{"owner":"sichos-277-position-0","section":277,"position":0,"source_index":1,"fields":{"he":"אמר: שמעולם לא שתה אפלו מים קדם התפלה, והקפיד מאד על אלו השותין קאווע [קפה] וכיוצא בזה קדם התפלה.","he_nikud":"אָמַר: שֶׁמֵּעוֹלָם לֹא שָׁתָה אֲפִלּוּ מַיִם קֹדֶם הַתְּפִלָּה, וְהִקְפִּיד מְאֹד עַל אֵלּוּ הַשּׁוֹתִין קַאוֶוע [קפה] וְכַיּוֹצֵא בָּזֶה קֹדֶם הַתְּפִלָּה.","en":"The Rebbe said that he never drank even water before prayer, and he was greatly opposed to those who drink coffee [coffee] and the like before prayer."},"history":{"earlier_supplied_English":"The Rebbe said that he never as much as drank water before his morning prayers. He was greatly opposed to those who drank coffee and other beverages before praying. 362 Cf. Zohar II, 215b; ibid., III, 141b; Orach Chaim 89:3-4; Be'er Hetiv 89:11.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-277-original.json","original_owner_pointer":"/segments/0"},"required_qualifications":[{"id":"author271-origin-notice-sichos-277-position-0","owner":"sichos-277-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."},{"id":"author271-277-0-source-gloss","text":"“Coffee [coffee]” reproduces קאווע [קפה]: the source gives a Yiddish word followed by its Hebrew equivalent. The Hebrew says “before prayer” without adding “morning.”","owner":"sichos-277-position-0","placement":"after-owning-paragraph","role":"current-reader-limitation"}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-277-position-0","englishUTF8SHA256":"3ee74f16fb952f0a91eb69dcd5e1911d72d0f143357446d5cbeea7826f060d75"}},{"owner":"sichos-278-position-0","section":278,"position":0,"source_index":1,"fields":{"he":"אמר: שנמצאים כמה מאמרים בזהר הקדוש שגלה רבי שמעון בר יוחאי לתלמידיו אחר הסתלקותו!.","he_nikud":"אָמַר: שֶׁנִּמְצָאִים כַּמָּה מַאֲמָרִים בַּזֹּהַר הַקָּדוֹשׁ שֶׁגִּלָּה רַבִּי שִׁמְעוֹן בַּר יוֹחַאי לְתַלְמִידָיו אַחַר הִסְתַּלְּקוּתוֹ!.","en":"The Rebbe said that several sayings are found in the holy Zohar which Rabbi Shimon bar Yochai revealed to his disciples after his passing!"},"history":{"earlier_supplied_English":"The Rebbe said that many sayings in the Zohar were revealed by Rabbi Shimon bar Yochai to his disciples after his death.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-278-original.json","original_owner_pointer":"/segments/0"},"required_qualifications":[{"id":"author271-origin-notice-sichos-278-position-0","owner":"sichos-278-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-278-position-0","englishUTF8SHA256":"800c6e60c87ae96f72863eda4e8c000db2836c28f0f9b4b2dc3fbedf894e6e1c"}},{"owner":"sichos-278-position-1","section":278,"position":1,"source_index":2,"fields":{"he":"וזה ענין \"ובחבורא קדמאה\" שכתוב בזהר הקדוש בפרשת פינחס (ג ריט:) ובשאר מקומות. כי העולם אינם מבינים מהו ענין \"ובחבורא קדמאה\", אך האמת שהוא גלה להם כמה תורות אחר פטירתו, ומה שגלה להם קדם קרא חבורא קדמאה.","he_nikud":"וְזֶה עִנְיָן \"וּבַחֲבוּרָא קַדְמָאָה\" שֶׁכָּתוּב בַּזֹּהַר הַקָּדוֹשׁ בְּפָרָשַׁת פִּינְחָס (ג ריט:) וּבִשְׁאָר מְקוֹמוֹת. כִּי הָעוֹלָם אֵינָם מְבִינִים מַהוּ עִנְיָן \"וּבַחֲבוּרָא קַדְמָאָה\", אַךְ הָאֱמֶת שֶׁהוּא גִּלָּה לָהֶם כַּמָּה תּוֹרוֹת אַחַר פְּטִירָתוֹ, וּמַה שֶּׁגִּלָּה לָהֶם קֹדֶם קָרָא חֲבוּרָא קַדְמָאָה.","en":"And this is the matter of “and in the first compilation,” which is written in the holy Zohar in the portion of Pinchas (III, 219b) and in other places. For people do not understand the matter of “and in the first compilation,” but the truth is that he revealed several teachings to them after his death, and what he revealed to them before that he called the first compilation."},"history":{"earlier_supplied_English":"The Zohar speaks of a chaburah kadma'ah (first edition), and many do not understand what it is. It is mentioned in the Zohar (III, 219b) on the portion of Pinchas and in several other places. Rabbi Shimon revealed many lessons after his death.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-278-original.json","original_owner_pointer":"/segments/1"},"required_qualifications":[{"id":"author271-origin-notice-sichos-278-position-1","owner":"sichos-278-position-1","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."},{"id":"author271-278-1-prior-compilation","text":"The Hebrew calls what was revealed before Rabbi Shimon’s passing “the first compilation.” The comparison English instead places a “first assembly” after his passing; that is a different explanation, not the reading followed here.","owner":"sichos-278-position-1","placement":"after-owning-paragraph","role":"current-reader-limitation"}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-278-position-1","englishUTF8SHA256":"cad138555fb3eafa4583119d0121d04837b583131eb35b2fa909da372e3baff1"}},{"owner":"sichos-278-position-2","section":278,"position":2,"source_index":3,"fields":{"he":"ובזה מישב היטב מה שנמצאים בספרי הזהר הקדוש ובתקונים פרוש על מימרות האמוראים שהיו אחר רבי שמעון בר יוחאי זמן מרבה. אך באמת אלו המאמרים גלה רבי שמעון בר יוחאי אחר פטירתו ואז כבר היו אלו האמוראים בעולם.","he_nikud":"וּבָזֶה מְיֻשָּׁב הֵיטֵב מַה שֶּׁנִּמְצָאִים בְּסִפְרֵי הַזֹּהַר הַקָּדוֹשׁ וּבַתִּקּוּנִים פֵּרוּשׁ עַל מֵימְרוֹת הָאֲמוֹרָאִים שֶׁהָיוּ אַחַר רַבִּי שִׁמְעוֹן בַּר יוֹחַאי זְמַן מְרֻבֶּה. אַךְ בֶּאֱמֶת אֵלּוּ הַמַּאֲמָרִים גִּלָּה רַבִּי שִׁמְעוֹן בַּר יוֹחַאי אַחַר פְּטִירָתוֹ וְאָז כְּבָר הָיוּ אֵלּוּ הָאֲמוֹרָאִים בָּעוֹלָם.","en":"And this explains well why the books of the holy Zohar and the Tikunim contain explanations of sayings of Amora’im who lived a long time after Rabbi Shimon bar Yochai. But in truth Rabbi Shimon bar Yochai revealed these sayings after his death, and by then these Amora’im were already in the world."},"history":{"earlier_supplied_English":"The lessons revealed during his lifetime comprised the chaburah kadma'ah, the first edition of the Zohar . It is therefore not surprising that the Zohar and Tikkuney Zohar explain many sayings of Amora'im , masters of the Talmud who lived many years after Rabbi Shimon passed away. The meaning of these sayings was revealed by Rabbi Shimon after his death, during the lifetime of these Amora'im .","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-278-original.json","original_owner_pointer":"/segments/2"},"required_qualifications":[{"id":"author271-origin-notice-sichos-278-position-2","owner":"sichos-278-position-2","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-278-position-2","englishUTF8SHA256":"ab060e97ce9da69be71d5fd7a09c1cd46cf1fb7a623effa290269d37553ed8ef"}},{"owner":"sichos-278-position-3","section":278,"position":3,"source_index":4,"fields":{"he":"אחר כך מצאתי ענין זה באיזה ספר.","he_nikud":"אַחַר כָּךְ מָצָאתִי עִנְיַן זֶה בְּאֵיזֶה סֵפֶר.","en":"Later, I found this matter in a certain book."},"history":{"earlier_supplied_English":"Later, we found a similar concept in another work. 363 Kisey Melekh on Tikkuney Zohar #7, “ BeAgada ” (7b) (Jerusalem, 5723).","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-278-original.json","original_owner_pointer":"/segments/3"},"required_qualifications":[{"id":"author271-origin-notice-sichos-278-position-3","owner":"sichos-278-position-3","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."},{"id":"author271-278-3-unnamed-book","text":"The book is unnamed in the Hebrew. The detailed identification in the earlier English and the separate comparison note is not stated by this paragraph.","owner":"sichos-278-position-3","placement":"after-owning-paragraph","role":"current-reader-limitation"}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-278-position-3","englishUTF8SHA256":"17ad69f0f331f0c911b2a51dba67562aff1aeeb85961078bcc240ee34350325d"}},{"owner":"sichos-279-position-0","section":279,"position":0,"source_index":1,"fields":{"he":"פעם אחת אמר לי בזו הלשון: וכשכבר רע מאד אזי מתבטלים לגמרי (אין אז עס איז שוין גאר שלעכט. איז מין זיך גאר מבטל).","he_nikud":"פַּעַם אַחַת אָמַר לִי בְּזוֹ הַלָּשׁוֹן: וּכְשֶׁכְּבָר רַע מְאֹד אֲזַי מִתְבַּטְּלִים לְגַמְרֵי (אִין אַז עֶס אִיז שׁוֹין גָּאר שְׁלֶעכְט. אִיז מֶין זִיךְ גָּאר מְבַטֵּל).","en":"The Rebbe once told me in these words: “And when things are already very bad, then one nullifies oneself completely” (in Yiddish: “And when things are already very bad, then one nullifies oneself completely”)."},"history":{"earlier_supplied_English":"The Rebbe once told me, “ Uhn as es iz shoin gar schlecht, iz min zich gar mevatel – When things are very bad, make yourself into nothing.”","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-279-original.json","original_owner_pointer":"/segments/0"},"required_qualifications":[{"id":"author271-origin-notice-sichos-279-position-0","owner":"sichos-279-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."},{"id":"author271-279-0-Yiddish-rendering","text":"The Hebrew statement is followed by a Yiddish version. Both are translated into English here; the repeated meaning reflects the two statements in the source. The earlier transliteration remains a separate historical rendering.","owner":"sichos-279-position-0","placement":"after-owning-paragraph","role":"current-reader-limitation"}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-279-position-0","englishUTF8SHA256":"d7e09661c29bc90f07420134f7b1363a4577b77f9f684659d885bd8966345ae7"}},{"owner":"sichos-279-position-1","section":279,"position":1,"source_index":2,"fields":{"he":"ושאלתי אותו: איך מבטלין עצמו?","he_nikud":"וְשָׁאַלְתִּי אוֹתוֹ: אֵיךְ מְבַטְּלִין עַצְמוֹ?","en":"And I asked him, “How does one nullify oneself?”"},"history":{"earlier_supplied_English":"I asked him, “How does one make himself into nothing?”","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-279-original.json","original_owner_pointer":"/segments/1"},"required_qualifications":[{"id":"author271-origin-notice-sichos-279-position-1","owner":"sichos-279-position-1","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-279-position-1","englishUTF8SHA256":"6e40ed4e189447c108cb40c6942f0d5837c3389518770a252197db6274a421c4"}},{"owner":"sichos-279-position-2","section":279,"position":2,"source_index":3,"fields":{"he":"והשיב: סוגרין הפה והעינים והרי זה בטול (מע פאר מאכט דאס מויל און דיא אויגין איז בטול).","he_nikud":"וְהֵשִׁיב: סוֹגְרִין הַפֶּה וְהָעֵינַיִם וַהֲרֵי זֶה בִּטּוּל (מֶע פַאר מַאכְט דָּאס מוֹיל אוּן דִּיא אוֹיגְין אִיז בִּטּוּל).","en":"And he replied: “One closes the mouth and the eyes, and this is nullification” (in Yiddish: “One closes the mouth and the eyes; that is nullification”)."},"history":{"earlier_supplied_English":"He replied, “ Me far-macht das moil, uhn die oigen, iz men bitul – You close your mouth and eyes, and you are like nothing!”","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-279-original.json","original_owner_pointer":"/segments/2"},"required_qualifications":[{"id":"author271-origin-notice-sichos-279-position-2","owner":"sichos-279-position-2","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."},{"id":"author271-279-2-Yiddish-rendering","text":"The Hebrew reply is followed by a Yiddish version, both translated here. Both describe closing the mouth and eyes as nullification, not the literal nonexistence of the person.","owner":"sichos-279-position-2","placement":"after-owning-paragraph","role":"current-reader-limitation"}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-279-position-2","englishUTF8SHA256":"36fb099b7bcd10a20fe34b7c82cb3a05697019dd7311fc41a8833753f144775f"}},{"owner":"sichos-279-position-3","section":279,"position":3,"source_index":4,"fields":{"he":"מזה מובן עצה: שכשהבעל דבר מתגבר מאד מאד על האדם ומבלבל דעתו מאד בכמה מיני הרהורים רעים ובלבולים הרבה שקשה לו מאד לנצחם, אזי יבטל האדם עצמו לגמרי. כי כל האדם יכול לבטל עצמו לגמרי לפעמים. דהינו לסתם פיו ועיניו ולסלק דעתו לגמרי כאלו אין לו שום דעת ומחשבה כלל.","he_nikud":"מִזֶּה מוּבָן עֵצָה: שֶׁכְּשֶׁהַבַּעַל דָּבָר מִתְגַּבֵּר מְאֹד מְאֹד עַל הָאָדָם וּמְבַלְבֵּל דַּעְתּוֹ מְאֹד בְּכַמָּה מִינֵי הִרְהוּרִים רָעִים וּבִלְבּוּלִים הַרְבֵּה שֶׁקָּשֶׁה לוֹ מְאֹד לְנַצְּחָם, אֲזַי יְבַטֵּל הָאָדָם עַצְמוֹ לְגַמְרֵי. כִּי כָּל הָאָדָם יָכוֹל לְבַטֵּל עַצְמוֹ לְגַמְרֵי לִפְעָמִים. דְּהַיְנוּ לִסְתֹּם פִּיו וְעֵינָיו וּלְסַלֵּק דַּעְתּוֹ לְגַמְרֵי כְּאִלּוּ אֵין לוֹ שׁוּם דַּעַת וּמַחֲשָׁבָה כְּלָל.","en":"From this a counsel is understood: when the adversary overpowers a person very, very strongly and greatly confuses his mind with several types of evil thoughts and many confusions that are very difficult for him to overcome, then the person should nullify himself completely. For everyone can nullify himself completely at times. This means closing his mouth and his eyes and setting his mind aside completely, as if he had no awareness or thought at all."},"history":{"earlier_supplied_English":"We can gain valuable insight from these words. Sometimes you may feel overwhelmed by the Evil Urge. You are confused and disturbed by evil thoughts that are very difficult to overcome. You must then make yourself like nothing – you no longer exist, your eyes and mouth are closed. Every thought is banished. Your mind ceases to exist.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-279-original.json","original_owner_pointer":"/segments/3"},"required_qualifications":[{"id":"author271-origin-notice-sichos-279-position-3","owner":"sichos-279-position-3","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."},{"id":"author271-279-3-adversary","text":"“Adversary” renders בעל דבר in this context of evil thoughts. The source says “as if” one had no awareness or thought and separately states that everyone can do this at times. It does not assert literal personal or mental nonexistence; the comparison text’s different ethical explanation is not substituted.","owner":"sichos-279-position-3","placement":"after-owning-paragraph","role":"current-reader-limitation"}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-279-position-3","englishUTF8SHA256":"505c3558b8c346e460244a15cbfaeb8a6d98cdf933a61d47094097da7c2ce14d"}},{"owner":"sichos-279-position-4","section":279,"position":4,"source_index":5,"fields":{"he":"רק יבטל עצמו להשם יתברך לגמרי.","he_nikud":"רַק יְבַטֵּל עַצְמוֹ לְהַשֵּׁם יִתְבָּרַךְ לְגַמְרֵי.","en":"Rather, he should nullify himself completely before God, blessed be He."},"history":{"earlier_supplied_English":"You have nullified yourself completely before God (see Zimrat HaAretz #64) .","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-279-original.json","original_owner_pointer":"/segments/4"},"required_qualifications":[{"id":"author271-origin-notice-sichos-279-position-4","owner":"sichos-279-position-4","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-279-position-4","englishUTF8SHA256":"6de19edba45f64b7701a6081d6b58bbe504ded617e0a7ff8d9819108067e7af0"}},{"owner":"sichos-280-position-0","section":280,"position":0,"source_index":1,"fields":{"he":"שמעתי בשמו שאמר לענין מה שהצדיקים הם נעים ונדים בדרך, אמר: שיש נשמות נדחות שאינם יכולים להתעלות כי אם על ידי מה שהצדיק נע ונד.","he_nikud":"שָׁמַעְתִּי בִּשְׁמוֹ שֶׁאָמַר לְעִנְיַן מַה שֶּׁהַצַּדִּיקִים הֵם נָעִים וְנָדִים בַּדֶּרֶךְ, אָמַר: שֶׁיֵּשׁ נְשָׁמוֹת נִדָּחוֹת שֶׁאֵינָם יְכוֹלִים לְהִתְעַלּוֹת כִּי אִם עַל יְדֵי מַה שֶּׁהַצַּדִּיק נָע וָנָד.","en":"I heard in his name that he said, concerning tzaddikim wandering and roaming on the road: he said that there are outcast souls that cannot be elevated except through the tzaddik’s wandering and roaming."},"history":{"earlier_supplied_English":"The Rebbe spoke about tzaddikim who always wander and move about. He said, “There are outcast souls that cannot be elevated except through the wandering of a tzaddik. 364 See “ His Wisdom ” #195; Tzaddik #48. Cf. ibid., #87, #94; Yemey Moharnat #49.","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-280-original.json","original_owner_pointer":"/segments/0"},"required_qualifications":[{"id":"author271-origin-notice-sichos-280-position-0","owner":"sichos-280-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."},{"id":"author271-280-0-citation-discrepancy","text":"The primary Hebrew supplies no cross-reference here. The earlier English adds 195 and the comparison note adds 194; neither number is adopted as a citation supplied by this Hebrew paragraph.","owner":"sichos-280-position-0","placement":"after-owning-paragraph","role":"current-reader-limitation"}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-280-position-0","englishUTF8SHA256":"a8facb5f49f1ca9701ee281dc36d38395b5766ba0886bdee6dcb9050e024a38e"}},{"owner":"sichos-280-position-1","section":280,"position":1,"source_index":2,"fields":{"he":"ויש צדיק שאינו רוצה להיות נע ונד. אבל אף על פי כן הוא נע ונד בביתו. הינו, מה שהוא הולך הנה והנה בביתו זהו גם כן בחינת נע ונד.","he_nikud":"וְיֵשׁ צַדִּיק שֶׁאֵינוֹ רוֹצֶה לִהְיוֹת נָע וָנָד. אֲבָל אַף עַל פִּי כֵן הוּא נָע וָנָד בְּבֵיתוֹ. הַיְנוּ, מַה שֶּׁהוּא הוֹלֵךְ הֵנָּה וָהֵנָּה בְּבֵיתוֹ זֶהוּ גַּם כֵּן בְּחִינַת נָע וָנָד.","en":"And there is a tzaddik who does not want to wander and roam. But nevertheless he wanders and roams in his house. That is, his going back and forth in his house is also in the category of wandering and roaming."},"history":{"earlier_supplied_English":"“Even if the tzaddik does not want to travel, he roams and wanders in his house. He paces back and forth, and this is also in the category of wandering and roaming” (Genesis 4:12) .","original_source_url":"/reader/reviewed/sichos-271280-sources/sicha-280-original.json","original_owner_pointer":"/segments/1"},"required_qualifications":[{"id":"author271-origin-notice-sichos-280-position-1","owner":"sichos-280-position-1","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew text."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author271-origin-notice-sichos-280-position-1","englishUTF8SHA256":"3957dfcc124776a7ece959d3e75978e149c14e03bab74ee9d4a224dc8111bbec"}}];
